/**
 * Compare stable topic/section identities without merging procedures or inferring missing content.
 * State: request binds product and both known versions; section rows retain each exact source.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - interface ComparisonRequest: line 31
 * - type ChangeStatus: line 37
 * - interface SectionComparison: line 38
 * - interface TopicComparison: line 45
 * - variable MAX_TOPICS: line 59
 * - variable MAX_SECTIONS: line 60
 * - function comparisonUrl: line 63
 * - function sameWarning: line 76
 * - function sameSection: line 86
 * - function classify: line 97
 * - function sectionMap: line 104
 * - function compareTopics: line 116
 * - function comparisonRequests: line 207
 * @@SYMBOL_INDEX_END
 */

import type {
  Product,
  ProductVersion,
  TopicDocument,
  TopicSection,
  WarningNotice,
} from "./contracts";
import { topicUrl } from "./content";

export interface ComparisonRequest {
  readonly productId: string;
  readonly from: string;
  readonly to: string;
  readonly slug: string;
}
export type ChangeStatus = "added" | "absent" | "changed" | "unchanged";
export interface SectionComparison {
  readonly id: string;
  readonly before: TopicSection | undefined;
  readonly after: TopicSection | undefined;
  readonly status: ChangeStatus;
  readonly warningStatus: ChangeStatus | "none";
}
export interface TopicComparison {
  readonly request: ComparisonRequest;
  readonly product: Product;
  readonly fromVersion: ProductVersion;
  readonly toVersion: ProductVersion;
  readonly before: TopicDocument | undefined;
  readonly after: TopicDocument | undefined;
  readonly beforeUrl: string | undefined;
  readonly afterUrl: string | undefined;
  readonly sections: readonly SectionComparison[];
  readonly summaryChanged: boolean;
  readonly identifiersChanged: boolean;
  readonly sectionOrderChanged: boolean;
}
const MAX_TOPICS = 1000;
const MAX_SECTIONS = 128;

/** Validate path segments before making a shareable, root-relative canonical comparison link. */
export function comparisonUrl(request: ComparisonRequest): string {
  if (
    ![request.productId, request.slug].every(
      (part) => /^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(part) && part.length <= 128,
    ) ||
    ![request.from, request.to].every((part) => /^\d{1,6}\.\d{1,6}$/u.test(part))
  ) {
    throw new Error("invalid comparison path segment");
  }
  return `/compare/${request.productId}/${request.from}/${request.to}/${request.slug}/`;
}

/** Match structured warning values exactly; absence is never interpreted as the hazard being resolved. */
function sameWarning(left: WarningNotice | undefined, right: WarningNotice | undefined): boolean {
  return (
    left?.level === right?.level &&
    left?.condition === right?.condition &&
    left?.consequence === right?.consequence &&
    left?.avoidance === right?.avoidance
  );
}

/** Compare section content in authored order, including optional steps/code and every warning field. */
function sameSection(left: TopicSection, right: TopicSection): boolean {
  return (
    left.title === right.title &&
    JSON.stringify(left.paragraphs) === JSON.stringify(right.paragraphs) &&
    JSON.stringify(left.steps ?? []) === JSON.stringify(right.steps ?? []) &&
    left.code === right.code &&
    sameWarning(left.warning, right.warning)
  );
}

/** Classify one source pair; callers retain both sources instead of constructing a blended procedure. */
function classify(left: unknown, right: unknown, equal: boolean): ChangeStatus {
  if (left === undefined) return "added";
  if (right === undefined) return "absent";
  return equal ? "unchanged" : "changed";
}

/** Reject ambiguous stable section keys and bound comparison output before mapping differences. */
function sectionMap(topic: TopicDocument | undefined): ReadonlyMap<string, TopicSection> {
  const sections = topic?.sections ?? [];
  if (
    sections.length > MAX_SECTIONS ||
    new Set(sections.map((section) => section.id)).size !== sections.length
  ) {
    throw new Error("ambiguous or excessive section identities");
  }
  return new Map(sections.map((section) => [section.id, section]));
}

/** Compare exactly one product/topic in two catalog versions, retaining missing counterparts explicitly. */
export function compareTopics(
  topics: readonly TopicDocument[],
  products: readonly Product[],
  request: ComparisonRequest,
): TopicComparison {
  comparisonUrl(request);
  if (topics.length > MAX_TOPICS) throw new Error("comparison corpus exceeds 1000 topics");
  const product = products.find((entry) => entry.id === request.productId);
  const fromVersion = product?.versions.find((entry) => entry.version === request.from);
  const toVersion = product?.versions.find((entry) => entry.version === request.to);
  if (
    product === undefined ||
    fromVersion === undefined ||
    toVersion === undefined ||
    request.from === request.to
  ) {
    throw new Error("choose two distinct known versions of one product");
  }
  const scoped = topics.filter(
    (topic) =>
      topic.productId === product.id &&
      topic.topicSlug === request.slug &&
      (topic.version === request.from || topic.version === request.to),
  );
  const from = scoped.filter((topic) => topic.version === request.from);
  const to = scoped.filter((topic) => topic.version === request.to);
  if (from.length > 1 || to.length > 1) throw new Error("ambiguous stable topic identity");
  const before = from[0];
  const after = to[0];
  if (before === undefined && after === undefined)
    throw new Error("neither edition contains this topic");
  for (const [topic, version] of [
    [before, fromVersion],
    [after, toVersion],
  ] as const) {
    if (
      topic !== undefined &&
      (topic.lifecycle !== version.lifecycle || topic.productName !== product.name)
    ) {
      throw new Error("topic applicability disagrees with the public product catalog");
    }
  }
  const beforeSections = sectionMap(before);
  const afterSections = sectionMap(after);
  const ids = [...new Set([...beforeSections.keys(), ...afterSections.keys()])];
  const sections = ids.map((id): SectionComparison => {
    const left = beforeSections.get(id);
    const right = afterSections.get(id);
    return {
      id,
      before: left,
      after: right,
      status: classify(
        left,
        right,
        left !== undefined && right !== undefined && sameSection(left, right),
      ),
      warningStatus:
        left?.warning === undefined && right?.warning === undefined
          ? "none"
          : classify(left?.warning, right?.warning, sameWarning(left?.warning, right?.warning)),
    };
  });
  return {
    request,
    product,
    fromVersion,
    toVersion,
    before,
    after,
    beforeUrl: before === undefined ? undefined : topicUrl(before),
    afterUrl: after === undefined ? undefined : topicUrl(after),
    sections,
    summaryChanged:
      before !== undefined &&
      after !== undefined &&
      (before.summary !== after.summary || before.title !== after.title),
    sectionOrderChanged:
      before !== undefined &&
      after !== undefined &&
      JSON.stringify(before.sections.map((section) => section.id)) !==
        JSON.stringify(after.sections.map((section) => section.id)),
    identifiersChanged:
      before !== undefined &&
      after !== undefined &&
      JSON.stringify([...before.identifiers].sort()) !==
        JSON.stringify([...after.identifiers].sort()),
  };
}

/** Enumerate only real union-topic routes; missing counterparts get pages, unrelated diagnostics are not paired. */
export function comparisonRequests(
  topics: readonly TopicDocument[],
  products: readonly Product[],
): readonly ComparisonRequest[] {
  if (topics.length > MAX_TOPICS) throw new Error("comparison corpus exceeds 1000 topics");
  const requests: ComparisonRequest[] = [];
  for (const product of products) {
    for (const from of product.versions) {
      for (const to of product.versions) {
        if (from.version === to.version) continue;
        const slugs = [
          ...new Set(
            topics
              .filter(
                (topic) =>
                  topic.productId === product.id &&
                  (topic.version === from.version || topic.version === to.version),
              )
              .map((topic) => topic.topicSlug),
          ),
        ].sort();
        if (requests.length + slugs.length > 1000)
          throw new Error("comparison route budget exceeds 1000 pages");
        for (const slug of slugs)
          requests.push({ productId: product.id, from: from.version, to: to.version, slug });
      }
    }
  }
  return requests;
}
